create table if not exists public.staff_invitations (id uuid primary key default gen_random_uuid(),email text not null,user_id uuid,token_hash text not null unique,group_ids uuid[] not null,primary_group_id uuid,title text not null default '',department_ids uuid[] not null default '{}'::uuid[],primary_department_id uuid,staff_notes text not null default '',created_by uuid not null,created_at timestamptz not null default now(),expires_at timestamptz not null default (now()+interval '7 days'),accepted_at timestamptz,revoked_at timestamptz,constraint staff_invitation_email_lowercase check (email=lower(email)),constraint staff_invitation_groups_required check (cardinality(group_ids)>0)); alter table public.staff_invitations enable row level security;revoke all on public.staff_invitations from anon,authenticated;
create or replace function public.accept_staff_invitation(p_token text) returns jsonb language plpgsql security definer set search_path='public' as $$ declare inv public.staff_invitations%rowtype; actor uuid:=auth.uid(); actor_email text; chosen uuid; primary_slug text; has_super boolean; has_admin boolean; role_name text; dept text; begin
if actor is null then raise exception 'Sign in first'; end if; select lower(email) into actor_email from auth.users where id=actor; select * into inv from public.staff_invitations where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') for update; if not found then raise exception 'Invitation not found'; end if;
if inv.accepted_at is not null or inv.revoked_at is not null or inv.expires_at<=now() then raise exception 'Invitation no longer valid'; end if;
if actor_email is distinct from inv.email or (inv.user_id is not null and inv.user_id<>actor) then raise exception 'Use the invited customer email address'; end if;
if not exists(select 1 from public.user_profiles where id=actor) then raise exception 'Complete customer registration first'; end if;
if exists(select 1 from public.staff_members where user_id=actor) then raise exception 'Staff access already exists'; end if;
if exists(select 1 from unnest(inv.group_ids) g left join public.staff_groups sg on sg.id=g where sg.id is null) then raise exception 'Invalid group'; end if;
chosen:=case when inv.primary_group_id=any(inv.group_ids) then inv.primary_group_id else inv.group_ids[1] end;select slug into primary_slug from public.staff_groups where id=chosen;
select exists(select 1 from public.staff_groups where id=any(inv.group_ids) and slug='superadmin') into has_super;select exists(select 1 from public.staff_groups where id=any(inv.group_ids) and slug='admin') into has_admin;
role_name:=case when has_super then 'superadmin' when has_admin then 'admin' when primary_slug='senior-support' then 'senior-support' else 'support' end;
select name into dept from public.support_departments where id=inv.primary_department_id and enabled=true;
insert into public.staff_members(user_id,status,title,department,staff_notes,created_by,updated_at) values(actor,'active',nullif(trim(inv.title),''),dept,nullif(trim(inv.staff_notes),''),inv.created_by,now());
insert into public.staff_member_groups(user_id,group_id,is_primary) select actor,g,(g=chosen) from unnest(inv.group_ids) g;
if cardinality(inv.department_ids)>0 then insert into public.support_department_staff(user_id,department_id) select actor,d from unnest(inv.department_ids) d join public.support_departments sd on sd.id=d and sd.enabled=true on conflict do nothing;end if;
update public.user_profiles set role=role_name where id=actor;update public.staff_invitations set accepted_at=now(),user_id=actor where id=inv.id;
insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(actor,'staff.invitation_accepted','staff_member',actor::text,jsonb_build_object('invitation_id',inv.id,'groups',inv.group_ids,'invited_by',inv.created_by));return jsonb_build_object('ok',true,'user_id',actor);end $$;revoke all on function public.accept_staff_invitation(text) from public,anon;grant execute on function public.accept_staff_invitation(text) to authenticated;